import{_ as o,c as a,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1791309864000}'),i={name:"guide/troubleshooting.md"};function n(s,e,l,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page collects common problems with nPlyr on macOS and iOS and how to resolve them.</p><h2 id="the-app-won-t-start-or-crashes-on-launch" tabindex="-1">The app won&#39;t start or crashes on launch <a class="header-anchor" href="#the-app-won-t-start-or-crashes-on-launch" aria-label="Permalink to &quot;The app won&#39;t start or crashes on launch&quot;">​</a></h2><ol><li>Make sure your OS meets the minimum (macOS 14 Sonoma+, or iOS / iPadOS 16+).</li><li>Quit and relaunch the app.</li><li>If you sideloaded a development build, make sure the provisioning profile is still valid.</li></ol><h2 id="a-video-won-t-play-spins-or-shows-an-error" tabindex="-1">A video won&#39;t play (spins or shows an error) <a class="header-anchor" href="#a-video-won-t-play-spins-or-shows-an-error" aria-label="Permalink to &quot;A video won&#39;t play (spins or shows an error)&quot;">​</a></h2><ul><li>Confirm the link is a <strong>direct</strong> media URL (<code>mp4</code>, <code>m3u8</code>, <code>flv</code>, <code>ts</code>, …), not a page. Use the <a href="/guide/browser.html">Browser &amp; Sniffer</a> to capture the real link.</li><li>Some sites require specific <strong>headers</strong> (referer, cookie, auth). Capturing the link through the sniffer preserves those headers automatically.</li><li><code>TS → MP4</code> passthrough needs a format hint; if a TS source fails, try a different line from the source switcher.</li><li>A <code>403</code> from a source is usually brief site-side rate limiting; wait and retry rather than changing headers blindly.</li></ul><h2 id="the-sniffer-captures-nothing-on-a-site" tabindex="-1">The sniffer captures nothing on a site <a class="header-anchor" href="#the-sniffer-captures-nothing-on-a-site" aria-label="Permalink to &quot;The sniffer captures nothing on a site&quot;">​</a></h2><ul><li>The page may load its video through a proprietary player or DRM that never requests a plain media file. In that case a <a href="/guide/miniapps.html">mini-program</a> that talks to the source&#39;s API is the right tool.</li><li>Try reloading the page, or switch the <strong>browser user-agent</strong> to Mobile / Desktop in <a href="/guide/settings.html">Settings</a>.</li></ul><h2 id="a-keyboard-shortcut-doesn-t-work" tabindex="-1">A keyboard shortcut doesn&#39;t work <a class="header-anchor" href="#a-keyboard-shortcut-doesn-t-work" aria-label="Permalink to &quot;A keyboard shortcut doesn&#39;t work&quot;">​</a></h2><ul><li>Shortcuts match on modifier keys only (<code>⌘</code>, <code>⌥</code>, <code>⌃</code>, <code>⇧</code>); direction keys and the numeric keypad are not part of the binding.</li><li>While you are typing in a text field (URL bar, search box), single-key shortcuts are intentionally suppressed so they don&#39;t fight your input.</li><li>If a binding still feels dead, check it isn&#39;t shadowed by a system or app shortcut in <strong>System Settings → Keyboard → Keyboard Shortcuts</strong>.</li></ul><h2 id="downloads-stall-or-fail" tabindex="-1">Downloads stall or fail <a class="header-anchor" href="#downloads-stall-or-fail" aria-label="Permalink to &quot;Downloads stall or fail&quot;">​</a></h2><ul><li>A per-segment failure marks the download <code>.failed</code>; resume from the marker files.</li><li>If a domain returns <code>404</code> repeatedly, nPlyr blacklists it for the session and will not silently reroute — pick another source.</li><li>Remux failures keep the raw <code>.ts</code> and mark it <code>completed</code>, so your data isn&#39;t lost.</li></ul><h2 id="a-mini-program-doesn-t-behave-like-on-android" tabindex="-1">A mini-program doesn&#39;t behave like on Android <a class="header-anchor" href="#a-mini-program-doesn-t-behave-like-on-android" aria-label="Permalink to &quot;A mini-program doesn&#39;t behave like on Android&quot;">​</a></h2><p>The original engine is Android/Java (Rhino). nPlyr runs rules on JavaScriptCore and implements a <strong>Rhino→Java compatibility layer</strong> for the parts rules depend on. Some Java-specific behavior is intentionally not supported. Check the <a href="/guide/miniapp-compatibility.html">Compatibility</a> page and, if a specific rule fails, report the rule name.</p><h2 id="resetting-nplyr" tabindex="-1">Resetting nPlyr <a class="header-anchor" href="#resetting-nplyr" aria-label="Permalink to &quot;Resetting nPlyr&quot;">​</a></h2><p>You can reset the app&#39;s local data (library, bookmarks, mini-program variables) from <strong>Settings → Advanced → Reset</strong>. This does not affect your purchased unlock.</p>',16)])])}const m=o(i,[["render",n]]);export{p as __pageData,m as default};
